def below_zero(operations: List[int]) -> bool:
    """Detect whether the account balance ever falls below zero."""
    balance = 0
    for amount in operations:
        balance += amount
        if balance < 0:
            return True
    return False

def find_topmost_carpet(n, carpets, point) -> int:
    """
    Finds the topmost carpet covering a given point on the coordinate plane.

    Args:
    n (int): The total number of carpets.
    carpets (list of tuples): A list containing n tuples, each representing a carpet's information.
                              Each tuple contains four integers (a, b, g, k) where (a, b) is the
                              coordinates of the bottom-left corner of the carpet and (g, k) are
                              the lengths of the carpet along the x and y axis respectively.
    point (tuple): A tuple containing two integers (x, y), the coordinates of the point to check.

    Returns:
    int: The number of the topmost carpet covering the point (x, y), or -1 if no carpet covers it.
    """
    # Basic input validation
    if not isinstance(point, (tuple, list)) or len(point) != 2:
        raise TypeError("point must be a tuple/list of length 2")
    x, y = point
    if not isinstance(x, int) or not isinstance(y, int):
        raise TypeError("point coordinates must be integers")

    if not isinstance(n, int) or n < 0:
        raise ValueError("n must be a non‑negative integer")
    if not isinstance(carpets, list) or len(carpets) != n:
        raise TypeError("carpets must be a list of length n")

    for idx, c in enumerate(carpets, start=1):
        if not isinstance(c, (tuple, list)) or len(c) != 4:
            raise TypeError(f"carpet at position {idx} must be a tuple/list of four integers")
        if not all(isinstance(v, int) for v in c):
            raise TypeError(f"carpet at position {idx} contains non‑integer values")

    top_index = -1
    for idx, (a, b, g, k) in enumerate(carpets, start=1):
        # Ignore carpets with non‑positive dimensions; zero‑width/height carpets only cover boundary
        if g < 0 or k < 0:
            continue
        if a <= x <= a + g and b <= y <= b + k:
            top_index = idx  # Since we traverse in order, the last match is topmost

    return top_index

