    """
    # Check that the provided encoded and original strings are of the same length
    if len(encoded) != len(original):
        return "Failed"

    # Build mapping from encoded to original and ensure bijectiveness
    mapping = {}
    reverse = {}  # to ensure each original letter maps from only one encoded letter
    for e_char, o_char in zip(encoded, original):
        if e_char in mapping:
            if mapping[e_char] != o_char:
                return "Failed"  # contradiction: same encoded letter maps to different originals
        else:
            if o_char in reverse:
                return "Failed"  # contradiction: different encoded letters map to the same original
            mapping[e_char] = o_char
            reverse[o_char] = e_char

    # Decode the message using the derived mapping
    decoded_chars = []
    for m_char in message:
        if m_char not in mapping:
            return "Failed"  # character in message has no mapping
        decoded_chars.append(mapping[m_char])

    return "".join(decoded_chars)

