        if e in enc_to_orig:
            if enc_to_orig[e] != o:
                return "Failed"
        else:
            enc_to_orig[e] = o
        if o in orig_to_enc:
            if orig_to_enc[o] != e:
                return "Failed"
        else:
            orig_to_enc[o] = e

