    return ''.join(decoded_chars)

def count_coprime_pairs(x0: int, y0: int) -> int:
    """
    Counts the number of ordered pairs (P, Q) of positive integers such that
    gcd(P, Q) = x0 and lcm(P, Q) = y0.

    Args:
        x0 (int): Desired greatest common divisor of the pair.
        y0 (int): Desired least common multiple of the pair.

    Returns:
        int: The number of valid ordered pairs (P, Q).
    """
    # Helper function to compute gcd without importing math
    def _gcd(a: int, b: int) -> int:
        while b:
            a, b = b, a % b
        return a

    # Basic validation
    if x0 <= 0 or y0 <= 0:
        return 0
    if y0 % x0 != 0:
        return 0

    n = y0 // x0  # product of the co-prime factors a * b
    count = 0
    limit = int(n ** 0.5) + 1
    for a in range(1, limit):
        if n % a == 0:
            b = n // a
            if _gcd(a, b) == 1:
                if a == b:
                    count += 1
                else:
                    count += 2
    return count

def generate_numbers(n, rules):
    if not isinstance(n, int) or not all(isinstance(r, tuple) and len(r)==2 and all(isinstance(d, int) for d in r) for r in rules):
        raise ValueError
    str_n=str(n)
    # Preprocess rules dict mapping digit char to list of replacement digits as char
    rules_map={}
    for x,y in rules:
        if not (0<=x<=9 and 0<=y<=9):
            continue # ignore invalid rules
        rules_map.setdefault(str(x), []).append(str(y))
    visited=set([int(str_n)])
    queue=[str_n]
    while queue:
        cur=queue.pop(0)
        for i,ch in enumerate(cur):
            if ch in rules_map:
                for rep in rules_map[ch]:
                    new_num_str=cur[:i]+rep+cur[i+1:]
                    new_int=int(new_num_str)
                    if new_int not in visited:
                        visited.add(new_int)
                        queue.append(new_num_str)
    return len(visited)

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """
    Evaluates the consistency of a scenario where one participant is the criminal based on the given statements.

    Parameters:
    - scenario (str): The name of the participant being tested as the potential criminal.
    - liar_count (set): A set of names of participants who are assumed to be liars.
    - statements (dict): A dictionary mapping participant names to lists of their respective statements.
    - days_of_week (set): A set of strings representing the days of the week.

    Returns:
    - bool: True if the scenario is consistent with the statements, False otherwise.
    """
    import re

    # Normalise scenario and days_of_week to upper case for comparison
    scenario_upper = scenario.upper()
    days_upper = {day.upper() for day in days_of_week}

    for speaker, speaker_statements in statements.items():
        speaker_upper = speaker.upper()
        for statement in speaker_statements:
            # Skip statements that mention a day of the week
            cleaned = re.sub(r'[^\w\s]', '', statement).upper()
            if any(day in cleaned.split() for day in days_upper):
                continue

            # Determine truth value of the statement
            truth = None

            # 1. Statements with "I"
            if cleaned.startswith("I AM"):
                if cleaned == "I AM GUILTY":
                    truth = (speaker_upper == scenario_upper)
                elif cleaned == "I AM NOT GUILTY":
                    truth = (speaker_upper != scenario_upper)

            # 2. Statements about another participant
            elif " IS " in cleaned:
                subject, rest = [part.strip() for part in cleaned.split(" IS ", 1)]
                if rest == "GUILTY":
                    truth = (subject == scenario_upper)
                elif rest == "NOT GUILTY":
                    truth = (subject != scenario_upper)

            # If statement doesn't match expected patterns, ignore it
            if truth is None:
                continue

            # Check liar status consistency
            if speaker_upper in liar_count:
                # Liars must say false statements
                if truth:
                    return False
            else:
                # Truth tellers must say true statements
                if not truth:
                    return False

    return True

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """
    Evaluate the consistency of a scenario with the given statements,
    assuming that participants in liar_count always lie.
    Disregards any statement that contains a day of the week.
    """
    import re

    # Normalise days of the week to lowercase for comparison
    days_lc = {day.lower() for day in days_of_week}

    # Helper to check if a statement is a day-related statement
    def is_day_statement(stmt: str) -> bool:
        stmt_lc = stmt.lower()
        return any(day in stmt_lc for day in days_lc)

    # Regular expressions for statement parsing
    i_guilty_re = re.compile(r"^i am guilty$")
    i_not_guilty_re = re.compile(r"^i am not guilty$")
    name_guilty_re = re.compile(r"^(\w+) is guilty$")
    name_not_guilty_re = re.compile(r"^(\w+) is not guilty$")

    # Determine if the scenario person is the guilty one
    def is_guilty(person: str) -> bool:
        return person == scenario

    for speaker, stmts in statements.items():
        # Whether this speaker is assumed to be a liar
        liar = speaker in liar_count

        for stmt in stmts:
            # Skip day-related statements
            if is_day_statement(stmt):
                continue

            # Clean statement: strip whitespace, lowercase, remove trailing periods
            stmt_clean = stmt.strip().lower().rstrip('.')

            # Identify the statement type
            truth = None  # Whether the statement is true under the scenario

            if i_guilty_re.match(stmt_clean):
                truth = is_guilty(speaker)
            elif i_not_guilty_re.match(stmt_clean):
                truth = not is_guilty(speaker)
            else:
                m = name_guilty_re.match(stmt_clean)
                if m:
                    name = m.group(1).strip().capitalize()
                    truth = is_guilty(name)
                else:
                    m = name_not_guilty_re.match(stmt_clean)
                    if m:
                        name = m.group(1).strip().capitalize()
                        truth = not is_guilty(name)

            # If we couldn't parse the statement, ignore it
            if truth is None:
                continue

            # Check consistency with liar status
            if liar:
                if truth:
                    # Liar said a true statement
                    return False
            else:
                if not truth:
                    # Truthful speaker said a false statement
                    return False

    return True

def vigenere_decrypt(key, ciphertext):
    if not key.isalpha():
        raise ValueError("Key must consist only of alphabetic characters.")
    if not ciphertext.isalpha():
        raise ValueError("Ciphertext must consist only of alphabetic characters.")
    if len(key)==0:
        raise ValueError("Key must not be empty.")
    result = []
    key_len = len(key)
    key_indices = [ord(c.lower()) - ord('a') for c in key]
    key_pos = 0
    for c in ciphertext:
        shift = key_indices[key_pos % key_len]
        if c.isupper():
            base = ord('A')
            cipher_idx = ord(c) - base
            plain_idx = (cipher_idx - shift) % 26
            result.append(chr(base + plain_idx))
        elif c.islower():
            base = ord('a')
            cipher_idx = ord(c) - base
            plain_idx = (cipher_idx - shift) % 26
            result.append(chr(base + plain_idx))
        else:
            # residual?
            result.append(c)
        key_pos += 1
    return ''.join(result)

def minimum_students_to_leave(heights):
    """
    Calculate the minimum number of students that need to leave to form a choir formation.
    A choir formation is defined such that for some position 'i', the heights of students
    increase from the start to 'i' and decrease from 'i' to the end of the formation.

    Args:
    heights (List[int]): A list of student heights.

    Returns:
    int: The minimum number of students that need to leave.
    """
    n = len(heights)
    if n <= 1:
        return 0  # no need to delete any student for a single or empty list

    # Longest increasing subsequence (LIS) length ending at each index
    inc = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and inc[j] + 1 > inc[i]:
                inc[i] = inc[j] + 1

    # Longest decreasing subsequence (LDS) length starting at each index
    dec = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i] and dec[j] + 1 > dec[i]:
                dec[i] = dec[j] + 1

    # Longest bitonic subsequence (mountain) length
    best = 0
    for i in range(n):
        cur = inc[i] + dec[i] - 1  # peak counted twice
        if cur > best:
            best = cur

    # Minimum deletions equals total minus longest mountain subsequence
    return n - best

